function LobbyStateSwitcher:Lobby_Enter()
    ---@see UGC_Lobby_Main_UIBP_C#OnUpdate
    LobbyUtils.OpenAndUpdateWidget(LobbyWidgetType.LWT_MainLobby, { ModeID = LobbyModel:GetCurrentSelectedModeID() })

    LobbyUtils.SwitchToLobbyCamera()
end

function LobbyStateSwitcher:Lobby_Leave()
    local PlayerController = UGCGameSystem.GetLocalPlayerController()
    PlayerController.IsCurrentUsePersistStateView = false
end

function LobbyStateSwitcher:ModeSelect_Enter()
    ---@see UGC_Lobby_Main_UIBP_C#OnClose
    LobbyUtils.CloseWidget(LobbyWidgetType.LWT_MainLobby)
    ---@see UGC_ModeSelection_UIBP_C#OnUpdate
    LobbyUtils.OpenAndUpdateWidget(LobbyWidgetType.LWT_ModeSelect, { FocusedMode = LobbyModel:GetCurrentSelectedModeID() })
end

function LobbyStateSwitcher:ModeSelect_Leave()
    LobbyUtils.CloseWidget(LobbyWidgetType.LWT_ModeSelect)
end

function LobbyStateSwitcher:ExitConfirm_Enter()
    LobbyUtils.OpenWidget(LobbyWidgetType.LWT_ClosePopupsTips)
end

function LobbyStateSwitcher:ExitConfirm_Leave()
    LobbyUtils.CloseWidget(LobbyWidgetType.LWT_ClosePopupsTips)
end

function LobbyStateSwitcher:TalentTree_Enter()
    LobbyUtils.OpenAndUpdateWidget(LobbyWidgetType.LWT_TalentTree)
end

function LobbyStateSwitcher:TalentTree_Leave()
    LobbyUtils.CloseWidget(LobbyWidgetType.LWT_TalentTree)
end

function LobbyStateSwitcher:HeroSelection_Enter()
    LobbyUtils.CloseWidget(LobbyWidgetType.LWT_MainLobby)

    self.OnHeroSelectionClosed = function (self)
        LobbyFlow:Go(LobbyFlowState.LFS_Lobby)
    end

    HeroSelectionManager.OnMainWidgetClosed:Add(self.OnHeroSelectionClosed, self)
    HeroSelectionManager:OpenMainWidget()
end

function LobbyStateSwitcher:HeroSelection_Leave()
    HeroSelectionManager.OnMainWidgetClosed:Remove(self.OnHeroSelectionClosed, self)
end

function LobbyStateSwitcher:Warehouse_Enter()
    self.OnBackpackClosed = function (self)
        LobbyFlow:Go(LobbyFlowState.LFS_Lobby)
    end
    print("[LobbyStateSwitcher:Warehouse_Enter]");

    local BackPackUICloseDelegate = UGCBackpackSystemV2.GetBackpackUIClosedDelegate()

    if BackPackUICloseDelegate then
        BackPackUICloseDelegate:Add(self.OnBackpackClosed, self)
        print("[LobbyStateSwitcher:Warehouse_Enter]");
        UGCBackpackSystemV2.OpenBackpackPanel(3)
    end
end

function LobbyStateSwitcher:Warehouse_Leave()
    local BackPackUICloseDelegate = UGCBackpackSystemV2.GetBackpackUIClosedDelegate()
    if BackPackUICloseDelegate then
        BackPackUICloseDelegate:Remove(self.OnBackpackClosed, self)
    end
end

