function LobbyStateSwitcher:Switch(From, To)
    -- check From/To is valid
    do
        local IsValid = false
        if self:IsValid(From) and self:IsValid(To) then
            IsValid = true
        end

        if not IsValid then
            ugcprint("[LobbyStateSwitcher:Switch] Invalid From/To pram passed to switch state function")
            return
        end
    end

    -- do switch
    ugcprint("[LobbyStateSwitcher:Switch] Leaving: ".. From)
    LobbyStateSwitchFuncMap[From].Leave()

    if LobbyStateSwitchFuncMapSpec[From] and LobbyStateSwitchFuncMapSpec[From][To] then
        LobbyStateSwitchFuncMapSpec[From][To]()
    end

    ugcprint("[LobbyStateSwitcher:Switch] Entering: ".. To)
    LobbyStateSwitchFuncMap[To].Enter()
end

function LobbyStateSwitcher:CanSwitch(From, To)
    return LobbyStateConstraint[From][To] ~= nil
end

function LobbyStateSwitcher:IsValid(InState)
    if InState == nil then
        ugcprint("[LobbyStateSwitcher:IsValid] Invalid InState pram passed to switch state function, InState == nil")
        return false
    end

    if not type(InState) == "string" then
        ugcprint("[LobbyStateSwitcher:IsValid] Invalid InState pram passed to switch state function, type(InState) should be string")
        return false
    end

    for _, v in pairs(LobbyFlowState) do
        if v == InState then
            return true
        end
    end

    ugcprint("[LobbyStateSwitcher:IsValid] Invalid InState pram passed to switch state function, InState not in LobbyState")
    return false
end


return LobbyStateSwitcher